  status: "idle",
  principal: null,
  lastCorrelationId: null,
};

export function hasAnyPermission(
  principal: PrincipalSessionResponse | null,
  candidates: readonly string[],
): boolean {
  if (!principal || !Array.isArray(principal.permissions)) {
    return false;
  }
  const normalizedSet = new Set(
    principal.permissions.map((perm) => perm.trim().toLowerCase()),
  );
  return candidates.some((candidate) =>
    normalizedSet.has(candidate.trim().toLowerCase()),
  );
}

export function isZeroRoleOnboardingPrincipal(
  principal: PrincipalSessionResponse | null,
): boolean {
  if (!principal) {
    return false;
  }
  return (
    principal.redirectView === "ROLE_APPLY_ONBOARDING" ||
    !Array.isArray(principal.roles) ||
    principal.roles.length === 0
  );
}
