"import { AccessDeniedPage } from "../../pages/AccessDeniedPage";
import { DashboardPage } from "../../pages/DashboardPage";
import { RoleApplyOnboardingPage } from "../../pages/RoleApplyOnboardingPage";
import { WorkspacePlaceholderPage } from "../../pages/WorkspacePlaceholderPage";
import { usePortalStore } from "../../store/PortalStoreProvider";
import {
  hasAnyPermission,
  isZeroRoleOnboardingPrincipal,
} from "../../store/slices/sessionSlice";
import { WORKSPACE_NAV_ITEMS } from "./PrimaryWorkspaceNav";

export function RoutePermissionGuard() {
  const { session, currentPath } = usePortalStore();
  const principal = session.principal;

  if (!principal) {
    return null;
  }

  const normalizedPath = currentPath === "/" ? "/dashboard" : currentPath;

  if (
    isZeroRoleOnboardingPrincipal(principal) ||
    normalizedPath === "/onboarding/role-apply"
  ) {
    return <RoleApplyOnboardingPage />;
  }

  const matchedRoute = WORKSPACE_NAV_ITEMS.find(
    (item) => item.path === normalizedPath,
  );

  if (!matchedRoute) {
    return <AccessDeniedPage />;
  }

  if (!hasAnyPermission(principal, matchedRoute.requiredPermissions)) {
    return <AccessDeniedPage />;
  }

  if (matchedRoute.path === "/dashboard") {
    return <DashboardPage />;
  }

  return (
    <WorkspacePlaceholderPage
      title={matchedRoute.label}
      routePath={matchedRoute.path}
    />
  );
}
